ca_init <- function(con) {
DBI::dbExecute(con,"CREATE TABLE IF NOT EXISTS collective_action_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, scope_key TEXT NOT NULL, course TEXT NOT NULL, sections TEXT NOT NULL, title TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP)")
DBI::dbExecute(con,"CREATE TABLE IF NOT EXISTS collective_action_rounds (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER NOT NULL, scope_key TEXT NOT NULL, sequence INTEGER NOT NULL, mechanism TEXT NOT NULL, endowment REAL NOT NULL, multiplier REAL, threshold_formula TEXT, threshold_value REAL, reward_type TEXT, reward_payload TEXT, status TEXT NOT NULL DEFAULT 'draft', opened_at TEXT, locked_at TEXT, revealed_at TEXT, UNIQUE(session_id,sequence))")
DBI::dbExecute(con,"CREATE TABLE IF NOT EXISTS collective_action_members (round_id INTEGER NOT NULL, user_id TEXT NOT NULL, scope_key TEXT NOT NULL, endowment REAL NOT NULL, PRIMARY KEY(round_id,user_id))")
DBI::dbExecute(con,"CREATE TABLE IF NOT EXISTS collective_action_choices (round_id INTEGER NOT NULL, user_id TEXT NOT NULL, scope_key TEXT NOT NULL, contributed REAL NOT NULL DEFAULT 0, revision INTEGER NOT NULL DEFAULT 1, submitted_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(round_id,user_id))")
DBI::dbExecute(con,"CREATE TABLE IF NOT EXISTS collective_action_outcomes (round_id INTEGER PRIMARY KEY, scope_key TEXT NOT NULL, eligible_n INTEGER NOT NULL, total_contributed REAL NOT NULL, threshold_value REAL, unlocked INTEGER, calculated_at TEXT DEFAULT CURRENT_TIMESTAMP)")
DBI::dbExecute(con,"CREATE TABLE IF NOT EXISTS collective_action_payouts (round_id INTEGER NOT NULL, user_id TEXT NOT NULL, scope_key TEXT NOT NULL, kept REAL NOT NULL, pooled_return REAL NOT NULL, total REAL NOT NULL, PRIMARY KEY(round_id,user_id))")
}
ca_eval_formula <- function(formula,N,E=0,P=0) { txt<-gsub("[[:space:]]+","",as.character(formula)); if(!nzchar(txt)||grepl("[^0-9NEPceilfloorround+*/().,-]",txt)) stop("Unsupported formula"); env<-list2env(list(N=as.numeric(N),E=as.numeric(E),P=as.numeric(P)),parent=baseenv()); val<-eval(parse(text=txt),envir=env); if(!is.numeric(val)||length(val)!=1||!is.finite(val)||val<0) stop("Invalid formula"); as.numeric(val) }
ca_open_round <- function(con,round_id,members) { DBI::dbWithTransaction(con,{ r<-DBI::dbGetQuery(con,"SELECT scope_key,endowment,threshold_formula,status FROM collective_action_rounds WHERE id=?",params=list(round_id)); if(nrow(r)!=1||r$status[1]!="draft") stop("Round is not a draft"); ids<-unique(as.character(members)); ids<-ids[nzchar(ids)]; if(!length(ids)) stop("No members"); raw_threshold<-as.character(r$threshold_formula[1]); tv<-if(!is.na(raw_threshold) && nzchar(raw_threshold)) ca_eval_formula(raw_threshold,length(ids),r$endowment[1]) else NA_real_; for(uid in ids) DBI::dbExecute(con,"INSERT INTO collective_action_members(round_id,user_id,scope_key,endowment) VALUES(?,?,?,?)",params=list(round_id,uid,r$scope_key[1],r$endowment[1])); DBI::dbExecute(con,"UPDATE collective_action_rounds SET status='open',opened_at=CURRENT_TIMESTAMP,threshold_value=? WHERE id=? AND status='draft'",params=list(tv,round_id)) }) }
ca_submit_choice <- function(con,round_id,user_id,contribution) { contribution<-as.numeric(contribution); if(!is.finite(contribution)||contribution<0) stop("Invalid contribution"); DBI::dbWithTransaction(con,{ n<-DBI::dbExecute(con,"INSERT INTO collective_action_choices(round_id,user_id,scope_key,contributed) SELECT m.round_id,m.user_id,m.scope_key,? FROM collective_action_members m JOIN collective_action_rounds r ON r.id=m.round_id WHERE m.round_id=? AND m.user_id=? AND r.status='open' AND ?<=m.endowment ON CONFLICT(round_id,user_id) DO UPDATE SET contributed=excluded.contributed,revision=collective_action_choices.revision+1,updated_at=CURRENT_TIMESTAMP",params=list(contribution,round_id,user_id,contribution)); if(n!=1L) stop("Round is closed or contribution invalid") }); TRUE }
ca_lock_round <- function(con,round_id) { DBI::dbWithTransaction(con,{ r<-DBI::dbGetQuery(con,"SELECT * FROM collective_action_rounds WHERE id=?",params=list(round_id)); if(nrow(r)!=1||r$status[1]!="open") stop("Round is not open"); DBI::dbExecute(con,"UPDATE collective_action_rounds SET status='locked',locked_at=CURRENT_TIMESTAMP WHERE id=? AND status='open'",params=list(round_id)); m<-DBI::dbGetQuery(con,"SELECT m.user_id,m.scope_key,m.endowment,COALESCE(c.contributed,0) contributed FROM collective_action_members m LEFT JOIN collective_action_choices c ON c.round_id=m.round_id AND c.user_id=m.user_id WHERE m.round_id=?",params=list(round_id)); total<-sum(m$contributed); N<-nrow(m); unlocked<-if(r$mechanism[1]=="threshold")as.integer(total>=r$threshold_value[1])else 1L; DBI::dbExecute(con,"INSERT INTO collective_action_outcomes(round_id,scope_key,eligible_n,total_contributed,threshold_value,unlocked) VALUES(?,?,?,?,?,?)",params=list(round_id,r$scope_key[1],N,total,r$threshold_value[1],unlocked)); ret<-if(r$mechanism[1]=="linear")as.numeric(r$multiplier[1])*total/N else 0; for(i in seq_len(N)) DBI::dbExecute(con,"INSERT INTO collective_action_payouts(round_id,user_id,scope_key,kept,pooled_return,total) VALUES(?,?,?,?,?,?)",params=list(round_id,m$user_id[i],m$scope_key[i],m$endowment[i]-m$contributed[i],ret,m$endowment[i]-m$contributed[i]+ret)) }); TRUE }
